import { Button } from '@/components/ui/button';
import {
    Dialog,
    DialogClose,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import { DockDialogTrigger } from '@/components/Juridico/Details/juridico-action-dock-dialog-trigger';
import { DuePendingRequirementsPreview } from '@/components/Juridico/Details/DuePendingRequirementsPreview';
import { computePendingRequirementsForTransition } from '@/functions/juridico/due-status-transition';
import {
    scrollToDuePendingRequirements,
    toDueInputErrorTypes,
} from '@/functions/juridico/due-pending-requirements-flow';
import { useJuridicoDetailsStore } from '@/store/useJuridicoDetailsStore';
import type { ItensChecklist } from '@/types/due-diligence';
import React, { useMemo } from 'react';

type DialogProps = {
    trigger: React.ReactNode;
    title: string;
    description?: string;
    confirmButtonText?: string;
    confirmButtonFn?: () => void;
    cancelButtonText?: string;
    cancelButtonFn?: () => void;
    /** When set, shows pending checklist preview and blocks confirm until resolved. */
    phaseAdvance?: {
        currentStatus: string;
        targetStatus: string;
        requirementsData: ItensChecklist[];
        esfera?: string | null;
    };
};

/**
 *
 * @description Componente de modal genérico para ações jurídicas
 * @author Luiz Inaldo
 *
 * @param {Object} props - Propriedades do componente.
 * @param {React.ReactNode} props.trigger - Elemento que aciona o modal.
 * @param {string} props.title - Título do modal.
 * @param {string} [props.description] - (Opcional) Descrição do modal.
 * @param {string} [props.confirmButtonText] - (Opcional) Texto do botão de confirmação.
 * @param {Function} [props.confirmButtonFn] - (Opcional) Função do botão de confirmação. Pode receber argumentos ou não.
 * @param {string} [props.cancelButtonText] - (Opcional) Texto do botão de cancelamento.
 * @param {Function} [props.cancelButtonFn] - (Opcional) Função do botão de cancelamento. Pode receber argumentos ou não.
 *
 * @returns {JSX.Element} - Componente de modal renderizado
 */
export function JuridicoCommonDialog({
    trigger,
    title,
    description,
    confirmButtonText,
    confirmButtonFn,
    cancelButtonText,
    cancelButtonFn,
    phaseAdvance,
}: DialogProps) {
    const pendingRequirements = useMemo(() => {
        if (!phaseAdvance) {
            return [];
        }

        return computePendingRequirementsForTransition(
            phaseAdvance.requirementsData,
            phaseAdvance.currentStatus,
            phaseAdvance.targetStatus,
            { esfera: phaseAdvance.esfera },
        );
    }, [phaseAdvance]);

    const hasBlockingPending = pendingRequirements.length > 0;

    function handleGoToRequirements() {
        useJuridicoDetailsStore
            .getState()
            .setRequiredInputsErrorType(toDueInputErrorTypes(pendingRequirements));
        scrollToDuePendingRequirements(pendingRequirements);
    }

    function handleConfirm(event: React.MouseEvent<HTMLButtonElement>) {
        event.stopPropagation();

        if (hasBlockingPending) {
            handleGoToRequirements();
            return;
        }

        confirmButtonFn?.();
    }

    return (
        <Dialog>
            <DockDialogTrigger trigger={trigger} />
            <DialogContent hideClose>
                <DialogHeader>
                    <DialogTitle>{title}</DialogTitle>
                    {description && <DialogDescription>{description}</DialogDescription>}
                </DialogHeader>

                {hasBlockingPending && (
                    <DuePendingRequirementsPreview
                        requisitos={pendingRequirements}
                        title="Conclua os itens abaixo antes de confirmar o avanço de fase."
                    />
                )}

                <DialogFooter>
                    {hasBlockingPending ? (
                        <DialogClose asChild>
                            <Button
                                size="flattened"
                                onClick={(event) => {
                                    event.stopPropagation();
                                    handleGoToRequirements();
                                }}
                                className="h-fit text-xs uppercase"
                            >
                                Ir para requisitos
                            </Button>
                        </DialogClose>
                    ) : (
                        <DialogClose asChild>
                            <Button
                                size="flattened"
                                onClick={handleConfirm}
                                className="h-fit text-xs uppercase"
                            >
                                {confirmButtonText || 'Sim'}
                            </Button>
                        </DialogClose>
                    )}
                    <DialogClose asChild>
                        <Button
                            variant="ghost"
                            size="flattened"
                            onClick={(event) => {
                                event.stopPropagation();
                                cancelButtonFn?.();
                            }}
                            className="h-fit text-xs uppercase"
                        >
                            {cancelButtonText || 'Não'}
                        </Button>
                    </DialogClose>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

