import { TOAST_INTERVAL_AWAIT_PROMISE } from '@/constants/constants';
import { QueryKeys } from '@/constants/query-keys';
import { DUE_DILIGENCE_STATUS_COLORS } from '@/constants/status';
import { useCollaborativeSectionLock } from '@/components/Collaboration/use-collaborative-section-lock';
import { invalidateDueDetailAndResume } from '@/components/Juridico/DueDiligence2/utils/invalidate-due-caches';
import { TOAST_LOADING_ID, sendToastMessage } from '@/functions/messages/toastMessage';
import { sleep } from '@/functions/timer/sleep';
import { maskCpfCnpj } from '@/functions/formaters/maskPii';
import { canAssumeDueResponsibility } from '@/functions/rulesVerification';
import {
    isAssumeResponsibilityConflict,
    refetchDueResponsavelSurfaces,
} from '@/functions/due-diligence/assume-responsibility-errors';
import { cn } from '@/lib/utils';
import {
    assumeDiligenceResponsibility,
    removeDiligenceResponsibility,
} from '@/services/due-diligence';

import { OficioDueDiligence, OficioDueDiligenceResponsavel } from '@/types/oficio';
import { useUserInfoStore } from '@/store/userInfo';
import queryClient from '@/utils/queryClient';
import { CreditCard, FileText, LoaderCircle, PencilLine, Trash } from 'lucide-react';
import { useTransition } from 'react';
import { Button } from '../Button';
import { JuridicoCommonDialog } from '../Modals/Juridico/JuridicoCommonDialog';
import { Avatar, AvatarFallback, AvatarImage } from '../ui/avatar';
import { Badge } from '../ui/badge';
import { DetailsCredorInfoProps } from './types';

const RESPONSAVEL_SECTION_ID = 'responsavel';

export const JuridicoDetailsCredorInfo = ({
    data,
    activeDue,
    dueId,
    extratoId,
    isLocked,
    responsavelData,
}: DetailsCredorInfoProps & {
    activeDue: OficioDueDiligence | undefined;
    dueId?: string;
    extratoId?: string;
    isLocked: boolean;
    responsavelData: OficioDueDiligenceResponsavel | null;
}) => {
    // ======================
    // # States
    // ======================
    const [isGettingDiligence, getDiligenceTransition] = useTransition();
    const userRole = useUserInfoStore((state) => state.data.role);
    const canAssumeDue = canAssumeDueResponsibility(userRole);
    const { acquireLock, releaseLock, isLockedByOther, sectionLock } =
        useCollaborativeSectionLock(RESPONSAVEL_SECTION_ID);

    // ======================
    // # Helpers
    // ======================
    const getDueDiligenceStatusColors = (status: string | undefined) => {
        if (!status) return DUE_DILIGENCE_STATUS_COLORS.TODOS;

        const statusColors =
            DUE_DILIGENCE_STATUS_COLORS[status as keyof typeof DUE_DILIGENCE_STATUS_COLORS] ||
            DUE_DILIGENCE_STATUS_COLORS.TODOS;

        return `${statusColors.bg} ${statusColors.text} ${statusColors.border}`;
    };

    function handleAssumeResponsibility() {
        const targetDueId = dueId ?? activeDue?.id;
        if (!targetDueId) return;

        getDiligenceTransition(async () => {
            const acquired = await acquireLock();
            if (!acquired) return;

            try {
                const result = await assumeDiligenceResponsibility(targetDueId);
                const alreadyWas =
                    typeof result?.message === 'string' &&
                    result.message.toLowerCase().includes('já é o responsável');
                sendToastMessage({
                    type: alreadyWas ? 'info' : 'success',
                    title: alreadyWas
                        ? 'Você já é o responsável. Atualizando a tela…'
                        : 'Você se tornou responsável por essa diligência.',
                });

                await sleep(TOAST_INTERVAL_AWAIT_PROMISE);

                sendToastMessage({
                    type: 'loading',
                    title: 'Atualizando dados do ofício.',
                });
                invalidateDueDetailAndResume(queryClient, targetDueId, { refetchType: 'all' });
                if (extratoId) {
                    await queryClient.invalidateQueries({
                        queryKey: [QueryKeys.oficios.item, extratoId],
                    });
                }
                sendToastMessage({
                    type: 'success',
                    title: 'Dados do ofício atualizados com sucesso!',
                    previousToastId: TOAST_LOADING_ID,
                });
            } catch (error) {
                if (isAssumeResponsibilityConflict(error)) {
                    await refetchDueResponsavelSurfaces(queryClient, targetDueId, extratoId);
                    sendToastMessage({
                        type: 'warning',
                        title: 'Outro usuário já assumiu esta due. A tela foi atualizada.',
                    });
                    return;
                }

                console.error('Error assuming responsibility:', error);
                sendToastMessage({
                    type: 'error',
                    title: 'Erro ao assumir responsabilidade. Tente novamente.',
                });
            } finally {
                releaseLock();
            }
        });
    }

    function handleRemoveResponsibility() {
        const targetDueId = dueId ?? activeDue?.id;
        if (!targetDueId) return;

        getDiligenceTransition(async () => {
            try {
                await removeDiligenceResponsibility(targetDueId);
                sendToastMessage({
                    type: 'success',
                    title: 'Você removeu a responsabilidade por essa diligência.',
                });

                await sleep(TOAST_INTERVAL_AWAIT_PROMISE);
                sendToastMessage({
                    type: 'loading',
                    title: 'Atualizando dados da diligência.',
                });
                invalidateDueDetailAndResume(queryClient, targetDueId, { refetchType: 'all' });
                if (extratoId) {
                    await queryClient.invalidateQueries({
                        queryKey: [QueryKeys.oficios.item, extratoId],
                    });
                }
                sendToastMessage({
                    type: 'success',
                    title: 'Dados da diligência atualizados com sucesso!',
                    previousToastId: TOAST_LOADING_ID,
                });
            } catch (error) {
                console.error('Error removing responsibility:', error);
                sendToastMessage({
                    type: 'error',
                    title: 'Erro ao remover responsabilidade. Tente novamente.',
                });
            }
        });
    }

    return (
        <div className="col-span-12 flex items-start justify-between rounded-md border bg-boxdark p-4 shadow-default">
            <div className="flex h-full w-full justify-between">
                <div className="flex gap-3">
                    <div className="shrink-0 self-start rounded-full bg-gray-100 p-2 dark:bg-slate-700">
                        <FileText className="size-8 text-paragraph" />
                    </div>
                    <div className="space-y-2">
                        <div>
                            <h3 className="text-base font-medium sm:text-lg">
                                {data?.credor || 'Credor não informado'}
                            </h3>
                            <p className="text-sm text-paragraph">ID do Ofício: {data?.id}</p>
                        </div>
                        <div className="flex items-center gap-4 text-paragraph">
                            <div className="flex items-center gap-2">
                                <CreditCard size={16} />
                                <p className="text-sm">
                                    {data?.cpf_cnpj?.length > 14 ? 'CNPJ' : 'CPF'}:{' '}
                                    {maskCpfCnpj(data?.cpf_cnpj) || 'Não informado'}
                                </p>
                            </div>
                            {activeDue?.status && (
                                <Badge
                                    className={cn(
                                        getDueDiligenceStatusColors(activeDue.status),
                                        'border font-medium',
                                    )}
                                >
                                    {activeDue.status_display}
                                </Badge>
                            )}
                        </div>
                    </div>
                </div>
                {!responsavelData && canAssumeDue ? (
                    <Button
                        variant="outline-success"
                        className="h-fit text-sm"
                        onClick={handleAssumeResponsibility}
                        disabled={isGettingDiligence || isLocked || isLockedByOther}
                        isLoading={isGettingDiligence}
                        title={
                            isLockedByOther && sectionLock
                                ? `${sectionLock.display_name || sectionLock.username} está assumindo ou editando o responsável`
                                : undefined
                        }
                    >
                        <PencilLine size={16} className="mr-2" />
                        Assumir Due
                    </Button>
                ) : responsavelData ? (
                    <div className="h-fit space-y-2 rounded-lg bg-boxdark-2 px-4 py-2">
                        <div className="relative flex flex-col items-center gap-2">
                            <Avatar className="size-8 shrink-0 border-2 border-title">
                                <AvatarImage src={responsavelData?.profile_picture} />
                                <AvatarFallback className="bg-linear-to-br from-blue-100 to-purple-100 text-sm text-blue-700">
                                    {responsavelData?.first_name.charAt(0).toUpperCase()}
                                    {responsavelData?.last_name.charAt(0).toUpperCase()}
                                </AvatarFallback>
                            </Avatar>
                            <div className="text-center">
                                <p className="text-sm font-medium text-subtitle">
                                    {responsavelData?.first_name} {responsavelData?.last_name}
                                </p>
                                <p className="text-xs text-paragraph">Responsável pela due</p>
                            </div>
                            <JuridicoCommonDialog
                                title="Remover Responsável pela Due"
                                description="Tem certeza que deseja remover o responsável pela due? Isso irá liberar a due para que outro usuário possa assumi-la."
                                confirmButtonFn={handleRemoveResponsibility}
                                trigger={
                                    <button
                                        title="Remover responsável"
                                        className="absolute right-0.5 top-0.5 cursor-pointer"
                                        disabled={isGettingDiligence || isLocked}
                                    >
                                        {isGettingDiligence ? (
                                            <LoaderCircle
                                                size={16}
                                                className="animate-spin text-red-500"
                                            />
                                        ) : (
                                            <Trash
                                                size={14}
                                                className="text-red-500 transition-colors duration-200 hover:text-red-700"

