'use client';

import { CessionarioMetricsGrid } from '@/components/Juridico/Details/CessionarioMetricsGrid';
import { ExtratoCessionarioEditModal } from '@/components/Juridico/Details/ExtratoCessionarioEditModal';
import { FinancePartyCard } from '@/components/Juridico/Details/finance/_components/FinancePartyCard';
import { JuridicoCommonDialog } from '@/components/Modals/Juridico/JuridicoCommonDialog';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ProductDialogDataField, productDialogOutlineButtonClass } from '@/design-system';
import { maskCpfCnpj } from '@/functions/formaters/maskPii';
import {
    canEditExtratoCessionarioLink,
    normalizeExtratoCessionarioPercentual,
    resolveExtratoCessionarioUnlinkId,
} from '@/functions/due-diligence/resolve-due-investidores';
import { resolvePctAquisicaoInvestidorDisplay } from '@/services/cessionario-vinculado';
import { useExtratoCessionarioUnlinkMutation } from '@/hooks/mutations/useExtratoCessionarioMutations';
import { OficioLinkedCedente } from '@/types/oficio';
import { LoaderCircle, PencilLine, Trash2, User } from 'lucide-react';

interface ExtratoCessionarioManageCardProps {
    link: OficioLinkedCedente;
    extratoId: string;
    dueId?: string;
    isLocked?: boolean;
    layout?: 'investidor' | 'finance';
}

function formatPercentualDisplay(value: string | number | null | undefined): string {
    const normalized = normalizeExtratoCessionarioPercentual(value, 'extrato');
    if (normalized === null || normalized === undefined || normalized === '') return '—';
    const numeric = Number(normalized);
    if (Number.isNaN(numeric)) return String(normalized);
    return `${numeric.toLocaleString('pt-BR', { maximumFractionDigits: 2 })}%`;
}

function formatDelimitadorDisplay(link: OficioLinkedCedente): string {
    if (!link.delimitador_ativo) return 'Desativado';
    if (link.delimitador_percentual == null || link.delimitador_percentual === '') {
        return 'Ativo (sem teto)';
    }
    return formatPercentualDisplay(link.delimitador_percentual);
}

export function ExtratoCessionarioManageCard({
    link,
    extratoId,
    dueId,
    isLocked = false,
    layout = 'investidor',
}: ExtratoCessionarioManageCardProps) {
    const unlinkMutation = useExtratoCessionarioUnlinkMutation({ extratoId, dueId });
    const cedenteNome = link.cedente?.nome?.trim() || 'Cessionário';
    const documentLabel = link.cedente?.documento
        ? maskCpfCnpj(link.cedente.documento) || link.cedente.documento
        : '—';
    const percentualDisplay = formatPercentualDisplay(link.percentual_cessao);
    const aquisicaoDisplay = resolvePctAquisicaoInvestidorDisplay(
        link.percentual_aquisicao_investidor,
        link.percentual_aquisicao_investidor_efetivo,
    );
    const delimitadorDisplay = formatDelimitadorDisplay(link);

    const canEdit = canEditExtratoCessionarioLink(link);
    const unlinkTargetId = resolveExtratoCessionarioUnlinkId(link);

    const actionButtons = !isLocked ? (
        <>
            {canEdit ? (
                <ExtratoCessionarioEditModal
                    link={link}
                    extratoId={extratoId}
                    dueId={dueId}
                    triggerButton={
                        <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            className={`h-8 gap-1.5 text-xs ${productDialogOutlineButtonClass}`}
                            aria-label={`Editar ${cedenteNome}`}
                        >
                            <PencilLine className="size-3.5" aria-hidden />
                            Editar
                        </Button>
                    }
                />
            ) : null}
            <JuridicoCommonDialog
                title="Remover cessionário do extrato?"
                description={`O vínculo de ${cedenteNome} com este ofício será removido. O cadastro do cessionário permanece no sistema.`}
                confirmButtonText="Remover"
                confirmButtonFn={() => unlinkMutation.mutate(unlinkTargetId)}
                cancelButtonText="Cancelar"
                trigger={
                    <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="h-8 gap-1.5 text-xs text-destructive hover:bg-destructive/10 hover:text-destructive"
                        disabled={unlinkMutation.isPending}
                        aria-label={`Remover ${cedenteNome} do extrato`}
                    >
                        {unlinkMutation.isPending ? (
                            <LoaderCircle className="size-3.5 animate-spin" aria-hidden />
                        ) : (
                            <Trash2 className="size-3.5" aria-hidden />
                        )}
                        Remover
                    </Button>
                }
            />
        </>
    ) : null;

    const metricsBlock = (
        <CessionarioMetricsGrid
            variant={layout === 'finance' ? 'stack' : 'grid'}
            percentualCessao={percentualDisplay}
            aquisicaoInvestidor={aquisicaoDisplay}
            delimitador={delimitadorDisplay}
        />
    );

    if (layout === 'finance') {
        return (
            <FinancePartyCard title="Cessionário" icon={User} actions={actionButtons} footer={metricsBlock}>
                <ProductDialogDataField label="Nome" value={cedenteNome} />
                <ProductDialogDataField label="Documento (CPF/CNPJ)" value={documentLabel} mono />
            </FinancePartyCard>
        );
    }

    return (
        <article className="space-y-3 rounded-xl border border-stroke bg-muted/5 p-4 dark:border-strokedark dark:bg-boxdark-2/40">
            <div className="flex flex-wrap items-start justify-between gap-2">
                <div className="min-w-0 space-y-1">
                    <h3
                        className="truncate text-sm font-semibold text-foreground"
                        title={cedenteNome}
                    >
                        {cedenteNome}
                    </h3>
                    <p className="truncate font-mono text-xs text-muted-foreground">{documentLabel}</p>
                </div>
                <div className="flex flex-col items-end gap-2">
                    <Badge variant="outline" className="shrink-0 text-[10px] uppercase tracking-wide">
                        Extrato
                    </Badge>
                    {actionButtons}
                </div>

