    TooltipProvider,
} from '@/components/ui/tooltip';
import dateFormater from '@/functions/formaters/dateFormater';
import { onSelectValueChangeGuard } from '@/functions/formGuardValues';
import { cn } from '@/lib/utils';
import Cleave from 'cleave.js/react';
import { Archive, Check, CircleStop, FileText, Loader, Plus, RefreshCw, Upload, X } from 'lucide-react';
import dynamic from 'next/dynamic';
import { useId, useMemo, useState } from 'react';
import { DueDiligenceProcessosSituacao } from '../../../enums';
import type { TProcessosFormLoadingStates } from '../../../interfaces/processos';
import type { TContabilizarDebitos, TProcessoJudicial } from '../../../types/dueItem';
import { isProcessoContabilizado } from '../../../utils/contabilizarDebitos';
import {
    DD_DOCUMENT_ALLOWED_HINT,
    DD_DOCUMENT_FILE_ACCEPT,
} from '../../../utils/dd-document-upload';
import { NPU_MAX_LENGTH, npuCleaveOptions, npuInputPlaceholder } from '../../../utils/npu-input';
import type { useViewModelProcessosForm } from '../../../ViewModels/useViewModelProcessosForm';
import { EspecieProcessoCombobox } from './EspecieProcessoCombobox';
import type { IGerenciarEspeciesProcessoModalProps } from './GerenciarEspeciesModal/index';
import type { ProcessosSummaryTipoLabels } from './ProcessosSummary';

const GerenciarEspeciesProcessoModal = dynamic<IGerenciarEspeciesProcessoModalProps>(
    () =>
        import('./GerenciarEspeciesModal/index').then(
            (mod) => mod.GerenciarEspeciesProcessoModal,
        ),
    { ssr: false },
);

const controlCls =
    'h-auto min-h-9 w-full rounded-lg border border-border bg-boxdark-2 px-2.5 py-1.5 text-[0.75rem] text-zinc-700 focus-visible:border-celer-blue/40 focus-visible:ring-0 dark:text-zinc-300 md:text-[0.75rem]';

/** Ícone do seletor de data ancorado à direita (WebKit / Firefox). */
const dateControlCls = cn(
    controlCls,
    'relative pr-10',
    '[&::-webkit-calendar-picker-indicator]:absolute [&::-webkit-calendar-picker-indicator]:right-2 [&::-webkit-calendar-picker-indicator]:top-1/2 [&::-webkit-calendar-picker-indicator]:-translate-y-1/2 [&::-webkit-calendar-picker-indicator]:cursor-pointer',
    '[&::-moz-calendar-picker-indicator]:absolute [&::-moz-calendar-picker-indicator]:right-2 [&::-moz-calendar-picker-indicator]:top-1/2 [&::-moz-calendar-picker-indicator]:-translate-y-1/2 [&::-moz-calendar-picker-indicator]:cursor-pointer',
);

const selectTriggerCls =
    'h-auto min-h-9 w-full rounded-lg border !border-border bg-boxdark-2 px-2.5 py-1.5 text-[0.75rem] font-normal normal-case text-zinc-700 shadow-none ring-offset-0 focus:ring-0 dark:text-zinc-300 [&>span]:text-[0.75rem] [&>span]:font-normal [&>span]:normal-case';

const selectItemCls = 'font-normal normal-case text-[0.75rem]';

const PROCESSO_FORM_LOADING = {
    saving: 'saving',
    archiving: 'archiving',
    suspending: 'suspending',
    concluding: 'concluding',
    restoring: 'restoring',
    reverting_conclusion: 'reverting_conclusion',
    migrating: 'migrating',
} as const satisfies Record<string, TProcessosFormLoadingStates>;

const MIGRAR_PRECATARIO_MODAL_DESCRIPTION =
    'Ao clicar em confirmar, o processo/recurso será migrado para o precatório e estará disponível para visualização em diligência';

const INSTANCIA_OPTIONS = ['1º Grau', '2º Grau', 'Instância Superior', 'Administrativo'];

const valorCausaCleaveOptions = {
    numeral: true,
    numeralThousandsGroupStyle: 'thousand' as const,
    numeralDecimalScale: 2,
    numeralDecimalMark: ',',
    delimiter: '.',
    prefix: 'R$ ',
    rawValueTrimPrefix: true,
};

const FASE_OPTIONS = ['Conhecimento', 'Cumprimento de Sentença/Execução', 'Monitória'];

