1	'use client';
2	
3	import { JuridicoCommonDialog } from '@/components/Modals/Juridico/JuridicoCommonDialog';
4	import { Button } from '@/components/ui/button';
5	import { Separator } from '@/components/ui/separator';
6	import { cn } from '@/lib/utils';
7	import { m, useReducedMotion } from 'framer-motion';
8	import { Link, Plus, X } from 'lucide-react';
9	
10	import {
11	    ADD_CEDENTE_SECTION_LABEL_CLASS,
12	    CEDENTE_SWITCHER_ITEM_ACTIVE_CLASS,
13	    CEDENTE_SWITCHER_ITEM_CLASS,
14	    CEDENTE_SWITCHER_SHELL_CLASS,
15	    SITUACAO_ADD_CEDENTE_BTN_CLASS,
16	} from '@/constants/due-diligence';
17	import { COLORS, ELEVATION } from '@/design-system';
18	import type { IAddCedenteSectionProps, ICedenteSwitcherProps } from '../../../interfaces/situacaoJuridicaViews';
19	import { isCessaoTotalmentePreenchida } from '../../../utils/situacaoJuridicaCedente';
20	import { getCedenteTipoLabel } from '../../../utils/situacaoJuridicaDisplay';
21	import {
22	    getSituacaoEnterMotion,
23	    getTitleThenCardsDelays,
24	    SITUACAO_STAGGER_STEP,
25	} from '../../../utils/situacaoJuridicaMotion';
26	import { CessaoPercentualSection } from '../Alerts/CessaoPercentualSection';
27	import { StatusPingDot } from '../StatusPingDot';
28	
29	function AddCedentePills({
30	    onAddCedente,
31	    onLinkExistingCedente,
32	    canAddCedente = true,
33	    baseDelay = 0,
34	    reduceMotion = false,
35	}: IAddCedenteSectionProps & { baseDelay?: number; reduceMotion?: boolean | null }) {
36	    if (!canAddCedente) {
37	        return null;
38	    }
39	
40	    const cedenteTipos = ['PF', 'PJ', 'ES'] as const;
41	    const { titleDelay, firstCardDelay } = getTitleThenCardsDelays(cedenteTipos.length, baseDelay);
42	
43	    return (
44	        <div
45	            className="min-w-0"
46	            role="group"
47	            aria-labelledby="add-cedente-section-label"
48	        >
49	            <m.span
50	                id="add-cedente-section-label"
51	                {...getSituacaoEnterMotion(reduceMotion, titleDelay)}
52	                className={ADD_CEDENTE_SECTION_LABEL_CLASS}
53	            >
54	                Adicionar novo cedente
55	            </m.span>
56	            <div className="flex flex-wrap items-center gap-2">
57	                {cedenteTipos.map((tipo, index) => (
58	                    <m.div
59	                        key={tipo}
60	                        {...getSituacaoEnterMotion(reduceMotion, firstCardDelay + index * SITUACAO_STAGGER_STEP)}
61	                    >
62	                        <Button
63	                            type="button"
64	                            variant="outline"
65	                            size="flattened"
66	                            onClick={() => onAddCedente(tipo)}
67	                            style={{
68	                                backgroundColor: COLORS.card,
69	                                borderColor: COLORS.line,
70	                                boxShadow: ELEVATION.surfaceRest,
71	                            }}
72	                            className={SITUACAO_ADD_CEDENTE_BTN_CLASS}
73	                        >
74	                            <Plus size={14} aria-hidden />
75	                            {getCedenteTipoLabel(tipo)}
76	                        </Button>
77	                    </m.div>
78	                ))}
79	                {onLinkExistingCedente ? (
80	                    <m.div
81	                        {...getSituacaoEnterMotion(
82	                            reduceMotion,
83	                            firstCardDelay + cedenteTipos.length * SITUACAO_STAGGER_STEP,
84	                        )}
85	                    >
86	                        <Button
87	                            type="button"
88	                            variant="outline"
89	                            size="flattened"
90	                            onClick={onLinkExistingCedente}
91	                            aria-label="Vincular cedente existente"
92	                            style={{
93	                                backgroundColor: COLORS.card,
94	                                borderColor: COLORS.line,
95	                                boxShadow: ELEVATION.surfaceRest,
96	                            }}
97	                            className={SITUACAO_ADD_CEDENTE_BTN_CLASS}
98	                        >
99	                            <Link size={14} aria-hidden />
100	                            vincular cedente existente
101	                        </Button>
102	                    </m.div>
103	                ) : null}
104	            </div>
105	        </div>
106	    );
107	}
108	
109	export function CedenteSwitcher({
110	    cedentesState,
111	    activeCedente,
112	    cessaoPercentualResumo,
113	    onSetActiveCedente,
114	    onAddCedente,
115	    onLinkExistingCedente,
116	    onRemoveCedente,
117	    isDesvinculandoCedente = false,
118	}: ICedenteSwitcherProps) {
119	    const reduceMotion = useReducedMotion();
120	
121	    if (cedentesState.length === 0) {
122	        return null;
123	    }
124	
125	    const showTabs = cedentesState.length > 1;
126	    const tabsCompleteDelay = showTabs
127	        ? getTitleThenCardsDelays(cedentesState.length, 0).cardsCompleteDelay
128	        : 0;
129	    const addSectionBaseDelay = showTabs ? tabsCompleteDelay + SITUACAO_STAGGER_STEP : 0;
130	    const cessaoSectionDelay = Math.max(0, addSectionBaseDelay - SITUACAO_STAGGER_STEP * 0.5);
131	    const canAddCedente = !isCessaoTotalmentePreenchida(cessaoPercentualResumo);
132	
133	    return (
134	        <div className="mb-4 flex w-full min-w-0 flex-col gap-3">
135	            {cessaoPercentualResumo ? (
136	                <CessaoPercentualSection
137	                    resumo={cessaoPercentualResumo}
138	                    baseDelay={cessaoSectionDelay}
139	                    reduceMotion={reduceMotion}
140	                    className="w-full"
141	                />
142	            ) : null}
143	            <div className="flex w-full min-w-0 flex-wrap items-center gap-x-3 gap-y-2">
144	                {showTabs ? (
145	                    <div
146	                        className={cn(CEDENTE_SWITCHER_SHELL_CLASS, 'min-w-0 shrink-0')}
147	                        role="tablist"
148	                        aria-label="Selecionar cedente"
149	                    >
150	                        {cedentesState.map((cedenteItem, index) => {
151	                            const isActive = index === activeCedente;
152	                            const cedente = cedenteItem.cedente;
153	                            const hasPending =
154	                                !cedente.processos_concluidos || !cedente.certidoes_concluidas;
155	
156	                            return (
157	                                <m.div
158	                                    key={cedenteItem.id || cedente.id || `cedente-tab-${index}`}
159	                                    {...getSituacaoEnterMotion(reduceMotion, index * SITUACAO_STAGGER_STEP)}
160	                                    className="relative"
161	                                >
162	                                    <button
163	                                        type="button"
164	                                        role="tab"
165	                                        aria-selected={isActive}
166	                                        onClick={() => onSetActiveCedente(index)}
167	                                        className={cn(
168	                                            CEDENTE_SWITCHER_ITEM_CLASS,
169	                                            'min-w-[120px] max-w-[200px] pr-7',
170	                                            isActive && CEDENTE_SWITCHER_ITEM_ACTIVE_CLASS,
171	                                        )}
172	                                    >
173	                                        <span className="flex items-center gap-1.5">
174	                                            <span className="truncate text-sm font-semibold text-foreground">
175	                                                {cedente.nome || `Cedente ${index + 1}`}
176	                                            </span>
177	                                            <StatusPingDot
178	                                                hasPending={hasPending}
179	                                                size="sm"
180	                                                aria-label={
181	                                                    hasPending
182	                                                        ? 'Análises pendentes'
183	                                                        : 'Análises concluídas'
184	                                                }
185	                                            />
