} from '@/design-system/motion/juridico-action-dock-motion';
import {
    juridicoActionDockActionButtonClass,
    juridicoActionDockBodyClass,
    juridicoActionDockChevronClass,
    juridicoActionDockHeaderClass,
    juridicoActionDockListClass,
    juridicoActionDockShellClass,
    juridicoActionDockStatusLabelClass,
    juridicoActionDockStatusRowClass,
    juridicoActionDockTriggerClass,
    juridicoActionDockTriggerIconClass,
    juridicoActionDockTriggerSubtitleClass,
    juridicoActionDockTriggerTitleClass,
} from './juridico-action-dock-styles';

const JuridicoDetailsFloatActionMenu = ({
    data,
    activeDue,
    dueId,
    dueStatusCode,
    requirementsData,
    statusDisplayForUi,
    statusLiquidacao,
}: {
    data: DetailedOficioProps;
    activeDue: OficioDueDiligence | undefined;
    /** ID da due da página (invalidação de requisitos e status_display). */
    dueId: string;
    /** Código cru do status da due da página (pode divergir de `activeDue` no ofício). */
    dueStatusCode?: string;
    requirementsData: ItensChecklist[];
    /** Rótulo já normalizado V2→V1 (opcional; senão mapeia a partir de activeDue). */
    statusDisplayForUi?: string;
    statusLiquidacao?: string | null;
}) => {
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    /** Mantém `max-h` do shell até o painel terminar o exit (evita “pulo” de altura ao fechar). */
    const [isDockLayoutExpanded, setIsDockLayoutExpanded] = useState(false);
    const prefersReducedMotion = useReducedMotion() === true;

    function openDockMenu() {
        setIsDockLayoutExpanded(true);
        setIsMenuOpen(true);
    }

    function closeDockMenu() {
        setIsMenuOpen(false);
    }

