'use client';

import { useEffect, useMemo, useState } from 'react';
import dynamic from 'next/dynamic';
import { useQueryState, parseAsString, parseAsInteger } from 'nuqs';
import { Handshake, Pencil, Plus, Search, Table2, Trash2, UserPlus } from 'lucide-react';
import { useAutoAnimate } from '@formkit/auto-animate/react';
import { useQueryClient } from '@tanstack/react-query';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
    COLORS,
    OperationalPageHeader,
    ProductDashedSurface,
    ProductSelect,
    TooltipHint,
} from '@/design-system';
import { TooltipProvider } from '@/components/ui/tooltip';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { QueryKeys } from '@/constants/query-keys';
import { APP_ROUTES } from '@/constants/app-routes';
import Link from 'next/link';
import {
    useArchiveCessionarioDdMutation,
    useCertidoesPadroesQuery,
    useCreateCessionarioDdMutation,
    useCessionarioDdDetailQuery,
    useCessionariosDdGestaoQuery,
    useUpdateCessionarioDdMutation,
} from '@/hooks/queries/cessionarios-dd';
import {
    padraoDueLabel,
    padraoCertidaoLabel,
    formatCessionarioCreatedAt,
    CESSIONARIO_ORDERING_OPTIONS,
    CESSIONARIO_PADRAO_CERTIDAO_NONE,
    PADRAO_DUE_OPTIONS,
    type CessionarioDdListItem,
    type CessionarioDdOrdering,
    type CessionarioDdWritePayload,
} from '@/services/cessionarios-dd';
import { CESSIONARIOS_GESTAO_PAGE_SIZE } from '@/constants/cessionarios-gestao';
import { CESSIONARIO_GESTAO_EDIT_QUERY_KEY } from '@/functions/cessionarios/cessionario-gestao-edit-url';
import { formatCessionarioUsuariosCell } from '@/functions/cessionarios/format-cessionario-usuarios-cell';
import { CPFAndCNPJMask } from '@/functions/formaters/CPFAndCNPJInput';
import { cn } from '@/lib/utils';

import { CessionarioArchiveDialog } from './cessionario-archive-dialog';
import { CessionarioFormDialog } from './cessionario-form-dialog';

const CessionarioCreateUserDialog = dynamic(
    () =>
        import('./cessionario-create-user-dialog').then(
            (m) => m.CessionarioCreateUserDialog,
        ),
    { ssr: false },
);

function documentLabel(item: CessionarioDdListItem): string {
    const raw = item.tipo === 'pf' ? item.cpf : item.cnpj;
    if (!raw?.trim()) return '—';
    return CPFAndCNPJMask(raw);
}

function documentDigits(item: CessionarioDdListItem): string {
    const raw = item.tipo === 'pf' ? item.cpf : item.cnpj;
    return raw?.trim() || '';
}

const TABLE_COLS =
    'grid-cols-[minmax(0,1.2fr)_minmax(0,0.9fr)_72px_minmax(0,0.8fr)_minmax(0,0.9fr)_88px_64px_minmax(0,0.9fr)_104px]';

export function CessionariosGestaoView() {
    const [search, setSearch] = useQueryState('q', parseAsString.withDefault(''));
    const [tipo, setTipo] = useQueryState('tipo', parseAsString.withDefault(''));
    const [padraoDue, setPadraoDue] = useQueryState('padrao_due', parseAsString.withDefault(''));
    const [padraoCertidao, setPadraoCertidao] = useQueryState(
        'padrao_certidao',
        parseAsString.withDefault(''),
    );
    const [ativo, setAtivo] = useQueryState('ativo', parseAsString.withDefault('true'));
    const [ordering, setOrdering] = useQueryState(
        'ordering',
        parseAsString.withDefault('-created_at'),
    );
    const [page, setPage] = useQueryState('page', parseAsInteger.withDefault(1));
    const [editId, setEditId] = useQueryState(CESSIONARIO_GESTAO_EDIT_QUERY_KEY, parseAsInteger);

    const listParams = useMemo(
        () => ({
            search: search || undefined,
            tipo: tipo || undefined,
            padrao_due: padraoDue || undefined,
            padrao_certidao: padraoCertidao || undefined,
            ativo: (ativo as 'true' | 'false' | '') || 'true',
            ordering: (ordering || '-created_at') as CessionarioDdOrdering,
            page: page || 1,
            page_size: CESSIONARIOS_GESTAO_PAGE_SIZE,
        }),

