export function ProcessosViewCore({ dueId, pessoaId }: TProcessosViewProps) {
    const router = useRouter();
    const relatorioProcessualService = useMemo(() => new RelatorioProcessualService(), []);

    const vm = useViewModelRelatorioProcessual({
        dueId,
        pessoaId,
        relatorioProcessualService,
        situacaoJuridicaService,
    });
    const itensElegiveis = useMemo(
        () =>
            vm.processosElegiveisPendencia.map((processo) => ({
                id: processo.id,
                titulo: buildProcessoPendenciaTitulo(processo),
                valorFormatado:
                    typeof processo.valor_causa === 'number' && processo.valor_causa > 0
                        ? formatCurrency(processo.valor_causa)
                        : undefined,
            })),
        [vm.processosElegiveisPendencia],
    );
    const concludeModal = useViewModelConcluirRelatorioDialog({
        open: vm.isConcludeModalOpen,
        origem: 'processo',
        isAllDocumentsUploaded: true,
        isLoading: vm.isConcludingAll,
        itensElegiveis,
        titularId: pessoaId,
        titularTipo: vm.tipoTitular,
        onClose: vm.onCloseConcludeModal,
        onConfirm: vm.onConfirmConcludeModal,
    });

    const handleVoltar = useCallback(() => {
        router.push(APP_ROUTES.private.dueDiligence.situacaoJuridica.name(dueId));
    }, [router, dueId]);

    if (vm.isLoading || !vm.due) {
        return <RelatorioProcessualLoadingSkeleton />;
    }

    if (vm.isTipoTitularMissing || vm.isTipoTitularInvalid) {
        return (
            <ProcessosErrorPanel
                message="Parâmetro tipoTitular ausente ou inválido. Acesse os processos pela Situação Jurídica."
                onVoltar={handleVoltar}
            />
        );
    }

